const Q4_SOL = "// ── ĐỀ CHO SẴN — KHÔNG SỬA ─────────────────────────────────────────────\n// Q4/health.cjs — mot app that, cac lan tham do that qua HTTP.\nconst http = require('node:http');\nconst IN = require('node:fs').readFileSync(0, 'utf8').trim().split('\\n');\n// Trang thai gia: DE CHO SAN, lam gia phu thuoc va do tre vong lap.\nconst state = { dbUp: true, redisUp: true, shuttingDown: false, eventLoopP99Ms: 1, dbHangs: false };\nconst withTimeout = (p, ms) =>\n  Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms).unref())]);\nconst pingDb = () => state.dbHangs ? new Promise(() => {})\n  : (state.dbUp ? Promise.resolve() : Promise.reject(new Error('ECONNREFUSED')));\nconst pingRedis = () => state.redisUp ? Promise.resolve() : Promise.reject(new Error('ECONNREFUSED'));\nconst app = http.createServer((req, res) => routes(req, res));\n\n// ── VIẾT LỜI GIẢI CỦA BẠN Ở ĐÂY ────────────────────────────────────────\n\nconst WEDGED_MS = 5000;\n\nasync function routes(req, res) {\n  const send = (code, body) => {\n    res.writeHead(code, { 'content-type': 'application/json' });\n    res.end(JSON.stringify(body));\n  };\n\n  // LIVENESS — khong I/O, khong phu thuoc. Chi truot khi CHINH tien trinh\n  // nay khong quay nua, vi he qua cua no la KHOI DONG LAI.\n  if (req.url === '/health/live') {\n    if (state.eventLoopP99Ms > WEDGED_MS) {\n      return send(503, { status: 'wedged', eventLoopP99Ms: state.eventLoopP99Ms });\n    }\n    return send(200, { status: 'ok', eventLoopP99Ms: state.eventLoopP99Ms });\n  }\n\n  // READINESS — cac phu thuoc, MOI CAI CO TRAN CHO. He qua la NGUNG GUI\n  // LUU LUONG, nen day moi la cho dat phep kiem phu thuoc.\n  if (req.url === '/health/ready') {\n    if (state.shuttingDown) return send(503, { status: 'shutting down' });\n    const checks = await Promise.allSettled([\n      withTimeout(pingDb(), 2000),\n      withTimeout(pingRedis(), 1000),\n    ]);\n    const db = checks[0].status === 'fulfilled';\n    const cache = checks[1].status === 'fulfilled';\n    // Redis la BO DEM: mat no thi HA CAP, khong phai chua san sang.\n    return send(db ? 200 : 503, {\n      status: db ? (cache ? 'ready' : 'degraded') : 'not ready',\n      database: db ? 'ok' : 'error',\n      cache: cache ? 'ok' : 'error',\n    });\n  }\n  return send(404, { status: 'not found' });\n}\n\n// ── ĐỀ CHO SẴN — KHÔNG SỬA ─────────────────────────────────────────────\nconst probe = (port, path) => new Promise((done) => {\n  const t0 = Date.now();\n  http.get({ host: '127.0.0.1', port, path }, (r) => {\n    let b = ''; r.on('data', (d) => (b += d));\n    r.on('end', () => done({ code: r.statusCode, body: b, slow: Date.now() - t0 > 1500 }));\n  });\n});\napp.listen(0, '127.0.0.1', async () => {\n  const port = app.address().port;\n  for (const line of IN) {\n    const [scenario, ...sets] = line.split('|').map((s) => s.trim());\n    Object.assign(state, { dbUp: true, redisUp: true, shuttingDown: false, eventLoopP99Ms: 1, dbHangs: false });\n    for (const kv of sets) { const [k, v] = kv.split('='); state[k] = v === 'true' ? true : v === 'false' ? false : Number(v); }\n    const live = await probe(port, '/health/live');\n    const ready = await probe(port, '/health/ready');\n    console.log(`${scenario.padEnd(22)} live=${live.code} ${live.body}`);\n    console.log(`${''.padEnd(22)} ready=${ready.code}${ready.slow ? ' (capped by timeout)' : ''} ${ready.body}`);\n  }\n  app.close();\n});";
